package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class StdDateFormat_isLenient_TriageGen2Test {







    @Test
    public void testIsLenient_ViaReflection() throws Exception {
        // Alternative way to ensure branch coverage for the null/non-null check 
        // if the constructor wasn't enough or to verify state directly.
        StdDateFormat df = new StdDateFormat();

        // Manually setting field to false via reflection to ensure we hit the booleanValue() path
        Field field = StdDateFormat.class.getDeclaredField("_lenient");
        field.setAccessible(true);
        field.set(df, Boolean.FALSE);

        assertFalse("Should return false when _lenient is explicitly set to false via reflection", df.isLenient());

        // Manually setting field to true
        field.set(df, Boolean.TRUE);
        assertTrue("Should return true when _lenient is explicitly set to true via reflection", df.isLenient());

        // Manually setting field back to null to ensure the null check works
        field.set(df, null);
        assertTrue("Should return true when _lenient is set back to null", df.isLenient());
    }
}
